userscript.function:

            //checkModule
            const module = {};
            if(sUtils.workflow.check('DSB')){
            	if(Sepoa.config.get('sepoa.supplier.default.profile_code') == Sepoa.info.MENU_PROFILE_CODE){
            		module.Contract = ['CT'].filter(moduleChecker).length > 0;
            	}else {
	                module.ReqSeal = ['USW', 'CSW'].filter(moduleChecker).length > 0;
	                module.SealMng = ['US', 'CS', 'SM', 'SR', 'SL'].filter(moduleChecker).length > 0;
	                module.SealExt = ['ET'].filter(moduleChecker).length > 0;
	                module.Contract = ['CT'].filter(moduleChecker).length > 0;
                    module.EmployeeContract = ['ECT'].filter(moduleChecker).length > 0;
                }
            }

            if(Sepoa.config.get('sepoa.system.manager.profile.code') == Sepoa.info.MENU_PROFILE_CODE){
                module.isSystemAdmin = true;
            }

            if(!sUtils.string.isBlank(Sepoa.info.MY_SEAL)){
                module.isSealOwner = true;
            }

            module.isSealManager = Sepoa.config.get('sepoa.seal.manager.porfile.code').split(',').indexOf(Sepoa.info.MENU_PROFILE_CODE) >= 0

            const ctrlList = Sepoa.info.CTRL_CODE.split(',');
            module.isMarkConfirmer = ctrlList.indexOf("SEAL_CONFIRM") >= 0
            module.isManageConfirmer = ctrlList.indexOf("MANAGE_CONFIRM") >= 0
            module.isExtConfirmer = ctrlList.indexOf("EXT_CONFIRM") >= 0
            module.isAttachConfirmer = ctrlList.indexOf("ATTACH_CONFIRM") >= 0

            //draw
            $share.dashboard.addItem({
                type: 'button',
                items:[{
                    text:'전체 메뉴 보기',
                    onclick:()=>{
                        callFunction('p', 'changeCarousel', ['summary'])
                    }
                }]
            });

            const date = new Date();
            date.setMonth(date.getMonth()-1);

            const defaultParams = {
            	// 커스텀 - 매 연단위 검색조건 요청
                F_CALENDAR_FROM: sUtils.date.toString(date, '20231005') ,
                F_CALENDAR_TO: sUtils.date.getToday()
            }

            if(module.ReqSeal || module.SealMng || module.SealExt){
                 const todoList = $share.dashboard.addItem({
                    label: Sepoa.cache.text.get('SUMMARY.TITLE_TODO_LIST'),
                    type: 'groupbox'
                });

                if(module.ReqSeal){
                    const group = todoList.addItem({
                        label: Sepoa.cache.text.get('SUMMARY.TITLE_REQ_SEAL')
                    });

                    const targetStatus = ['T'];
                    if(['USW1635987860041', 'CSW1635988016443'].filter(moduleChecker).length > 0){
                        targetStatus.push('I', 'R');
                    }
                    if(moduleChecker('CSW1635988016964')){
                        targetStatus.push('G', 'N');
                    }
                    if(moduleChecker('USW1637309480717')){
                        targetStatus.push('W', 'F');
                    }
                    if(['USW1635987861018', 'CSW1635988019236'].filter(moduleChecker).length > 0){
                        targetStatus.push('CR', 'C');
                    }

                    new Promise((rs, rj)=>{
                        setTimeout(()=>{
                            rs(sUtils.cache.combo.get('SL0001,'+Sepoa.info.HOUSE_CODE+'#'+Sepoa.info.LANGUAGE+'#SM032'));
                        })
                    }).then((allStatus)=>{
                        const filteredData = []
                        allStatus.forEach((item) => {
                            const targetIdx = targetStatus.indexOf(item.value);
                            if(targetIdx >= 0){
                                filteredData[targetIdx] = {
                                    id:item.value,   
                                    label:item.text,
                                    value:"...",
                                    events:{
                                        click:()=>{
                                            linkTo({
                                                id:"SLM_200",
                                                url:"/Seal/Document/Request/SealDocumentRequestLayout.sux",
                                                param:{
                                                    status:item.value
                                                },
                                                label:sUtils.cache.text.get('SLM_200.LAYOUT_A_HEADER')
                                            });
                                        }
                                    }
                                }
                            }
                        })

                        const list = group.addItem({
                            type:'list',
                            theme:'summary',
                            items:filteredData
                        });

                        if((moduleChecker('CSW1635988016964') && (module.isMarkConfirmer || module.isSystemAdmin))
                        || (moduleChecker('USW1637309480717') && module.isSealManager)){
                            list.addItem({
                                id:"TODO",
                                label:sUtils.cache.text.get("SLM_190.LAYOUT_A_HEADER"),
                                value:"...",
                                events:{
                                    click:()=>{
                                        linkTo({
                                            id:"SLM_190",
                                            url:"/Seal/Document/Todo/SealDocumentTodoLayout.sux",
                                            param:{
                                                status:'TODO'
                                            },
                                            label:sUtils.cache.text.get('SLM_190.LAYOUT_A_HEADER')
                                        });
                                    }
                                }
                            })
                        }

                        new Promise((rs, rj)=>{
                            sUtils.connector.service({
                                progress:false,
                                conType:"CONNECTION",
                                requestMode:"doServiceAjax",
                                async:true,
                                nickName:"sepoa.svc.seal.SepoaReqSealService",
                                methodName:"doCountRequestList",
                                callback:(so)=>{
                                    if(so.status == "1"){
                                        const counterObj = {};
                                        const resultStr = so.result[0];
                                        resultStr.substring(1, resultStr.length-1).split(',').forEach(val => {
                                            const kv = val.trim().split('=');
                                            counterObj[kv[0].replace('REQ_SEAL_COUNT_', '')] = kv[1];
                                        });
                                        rs(counterObj);
                                    }else{
                                        console.error(so)
                                        rj(false);
                                    }
                                }
                            }, {[Sepoa.common.KEY_PARAMS]:encodeURIComponent(sUtils.url.toSepoaParams(sUtils.object.extend(true, {}, defaultParams, {REQ_SEAL_STATUS_LIST:targetStatus.join(',')}),false))});
                        }).then((counter)=>{
                            list.setItemValue(counter);
                        })
                    })
                }

                if(module.SealMng){
                    const group = todoList.addItem({
                        label: Sepoa.cache.text.get('SUMMARY.TITLE_SEAL_MNG'),
                        width:180
                    })

                    const targetStatus = [];
                    if(['US', 'CS'].filter(moduleChecker).length > 0){
                        targetStatus.push('NE');
                    }

                    if (module.isSystemAdmin || module.isSealOwner || module.isSealManager) {
                        if(moduleChecker('SM')){
                            targetStatus.push('UP');
                        }
                        if(moduleChecker('SR')){
                            targetStatus.push('RE');
                        }
                        if(moduleChecker('SL')){
                            targetStatus.push('LO');
                        }
                    }

                    new Promise((rs, rj)=>{
                        setTimeout(()=>{
                            rs(sUtils.cache.combo.get('SL0002,'+Sepoa.info.HOUSE_CODE+'#'+Sepoa.info.LANGUAGE+'#SM031'));
                        })
                    }).then((allStatus)=>{
                        const filteredData = []
                        allStatus.forEach((item) => {
                            const targetIdx = targetStatus.indexOf(item.value);
                            if(targetIdx >= 0){
                                filteredData[targetIdx] = {
                                    id:item.value,
                                    label:item.text,
                                    value:"...",
                                    events:{
                                        click:()=>{
                                            linkTo({
                                                id:"SLM_170",
                                                url:"/Seal/Manage/SealManageRequestCarousel.sux",
                                                param:{
                                                    status:item.value
