                        if((module.isMarkConfirmer || module.isSystemAdmin) 
                            && (["US1635932977187", "CS1635987524638", "SM1635987583152", "SR1635987653583", "SL1635987694835"].filter(moduleChecker).length > 0)){
                            list.addItem({
                                id:"TODO",
                                label:sUtils.cache.text.get("SLM_160.LAYOUT_A_HEADER"),
                                value:"...",
                                events:{
                                    click:()=>{
                                        linkTo({
                                            id:"SLM_160",
                                            url:"/Seal/Manage/SealManageToDoCarousel.sux",
                                            param:{
                                                status:'TODO'
                                            },
                                            label:sUtils.cache.text.get('SLM_160.LAYOUT_A_HEADER')
                                        });
                                    }
                                }
                            })
                        }

                        new Promise((rs, rj)=>{
                            sUtils.connector.service({
                                progress:false,
                                conType:"CONNECTION",
                                requestMode:"doServiceAjax",
                                async:true,
                                nickName:"sepoa.svc.seal.SepoaSealManagementService",
                                methodName:"doCountRequestList",
                                callback:(so)=>{
                                    if(so.status == "1"){
                                        const counterObj = {};
                                        const resultStr = so.result[0];
                                        resultStr.substring(1, resultStr.length-1).split(',').forEach(val => {
                                            const kv = val.trim().split('=');
                                            counterObj[kv[0].replace('SEAL_MNG_COUNT_', '')] = kv[1];
                                        });
                                        rs(counterObj);
                                    }else{
                                        console.error(so)
                                        rj(false);
                                    }
                                }
                            }, {[Sepoa.common.KEY_PARAMS]:encodeURIComponent(sUtils.url.toSepoaParams(sUtils.object.extend(true, {}, defaultParams, {SEAL_MNG_TYPE_LIST:targetStatus.join(',')}),false))});
                        }).then((counter)=>{
                            list.setItemValue(counter);
                        })
                    })
                }

                if(module.SealExt){
                    const group = todoList.addItem({
                        label: Sepoa.cache.text.get('SUMMARY.TITLE_SEAL_EXT')
