                    }
                    if(moduleChecker('ET1644375000197')){
                        targetStatus.push('C');
                    }
                    if(moduleChecker('ET1644374538390')){
                        targetStatus.push('F');
                    }
                    if(moduleChecker('ET1644372420935')){
                        targetStatus.push('R');
