                                callback:(so)=>{
                                    if(so.status == "1"){
                                        const counterObj = {};
                                        const resultStr = so.result[0];
                                        resultStr.substring(1, resultStr.length-1).split(',').forEach(val => {
                                            const kv = val.trim().split('=');
                                            counterObj[kv[0].replace('SEAL_EXT_COUNT_', '')] = kv[1];
                                        });
                                        rs(counterObj);
                                    }else{
                                        console.error(so)
                                        rj(false);
                                    }
                                }
                            }, {[Sepoa.common.KEY_PARAMS]:encodeURIComponent(sUtils.url.toSepoaParams(sUtils.object.extend(true, {}, defaultParams, {SEAL_EXT_STATUS_LIST:targetStatus.join(',')}),false))});
                        }).then((counter)=>{
                            list.setItemValue(counter);
                        })
                    })
                }
            }

            /* if(module.Contract){
